from pathlib import Path
import re
r=Path(__file__).resolve().parent.parent
js=''
for n in ['model','store','calendar','assistant','engine']:
 s=(r/'src'/f'{n}.js').read_text();s=re.sub(r'^import .*?;\n','',s,flags=re.M);s=re.sub(r'\bexport (?=(?:async )?function|const|class)','',s);js+=s+'\n'
html='''<!DOCTYPE html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YOOKOO · Preview Thư ký</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f1f5f8;color:#17313e;font:15px system-ui,sans-serif}header{background:#123a46;color:white;padding:24px 5vw;display:flex;justify-content:space-between;align-items:center}h1{font-size:28px;margin:0}header p{margin:7px 0 0;color:#c1e2e3}.badge{background:#fdd68b;color:#523607;padding:9px 13px;border-radius:20px;font-weight:700;font-size:12px}.notice{margin:20px 5vw;padding:14px 20px;background:#fff8e9;border-left:4px solid #dc9b2d;line-height:1.6}main{margin:0 5vw 35px;display:grid;grid-template-columns:minmax(350px,1.1fr) minmax(330px,1fr);gap:22px}.card{background:white;border:1px solid #dbe5e9;border-radius:16px;overflow:hidden;box-shadow:0 5px 20px #17313e08}.cardhead{padding:18px 22px;border-bottom:1px solid #e5ecef;display:flex;justify-content:space-between;align-items:center}h2{font-size:18px;margin:0}.small{font-size:12px;color:#5c7580}.chat{height:510px;overflow:auto;padding:18px;background:#eaf4f2;display:flex;flex-direction:column;gap:12px}.bubble{max-width:92%;padding:13px 16px;white-space:pre-wrap;line-height:1.6;border-radius:14px;background:white;border:1px solid #d5e5e1}.bubble.user{align-self:flex-end;background:#cce9db}.controls{padding:16px;display:flex;gap:8px}input{flex:1;min-width:0;padding:13px;border:1px solid #bacbd0;border-radius:9px;font:inherit}button{cursor:pointer;border:0;border-radius:8px;padding:10px 14px;background:#0c7775;color:white;font:inherit}button:hover{filter:brightness(.93)}.examples{padding:0 16px 16px;display:flex;flex-wrap:wrap;gap:7px}.examples button,.slots button{font-size:12px;background:#e6f0f1;color:#234955}.right{display:flex;flex-direction:column;gap:20px}.slots{padding:15px;display:flex;gap:6px;flex-wrap:wrap}pre{font:13px/1.7 system-ui;white-space:pre-wrap;margin:0;padding:18px;max-height:330px;overflow:auto}.tasks{padding:0 16px 16px;max-height:370px;overflow:auto}.task{padding:12px 0;border-bottom:1px solid #e6ecef;line-height:1.5}.task strong{display:block;font-size:13px}.task span{font-size:12px;color:#566d78}.footer{padding:13px 20px;font-size:12px;color:#5c7580}.confirm{display:flex;gap:8px;padding:0 16px 12px}.confirm:empty{display:none}@media(max-width:800px){main{grid-template-columns:1fr}header{gap:14px}.chat{height:420px}h1{font-size:23px}.badge{font-size:10px}}
</style>
<header><div><h1>YOOKOO · Thư ký cá nhân</h1><p>Trao đổi nhanh · Theo dõi đúng phạm vi · Giữ lịch hiện có</p></div><span class="badge">PREVIEW · CHƯA TRIỂN KHAI</span></header>
<div class="notice">Bản mô phỏng dùng cùng logic quản lý công việc với bot. Không gọi AI, Telegram hay Google Calendar thật. Các nút bên dưới chỉ cập nhật phiên thử này; tải lại trang để khôi phục dữ liệu bàn giao. Thông báo ChatGPT không bị thay đổi.</div>
<main><section class="card"><div class="cardhead"><h2>💬 Hội thoại Telegram</h2><span class="small">Mẫu ngày 11/11/2026</span></div><div class="chat" id="chat"></div><form class="controls" id="form"><input id="input" placeholder="Ví dụ: Đã xong cống Km3+665" autocomplete="off"><button>Gửi</button></form><div id="confirm" class="confirm"></div><div class="examples" id="examples"></div><div class="footer">Hội thoại AI mở cần OPENAI_API_KEY + model. Preview thử được lệnh, cập nhật phạm vi, xác nhận, hoàn tác và ngoại lệ.</div></section>
<div class="right"><section class="card"><div class="cardhead"><h2>🕒 Năm mốc thư ký</h2><span class="small">Giờ Việt Nam</span></div><div class="slots" id="slots"></div><pre id="report"></pre></section><section class="card"><div class="cardhead"><h2>📋 Trạng thái công việc</h2><span id="revision" class="small"></span></div><div id="tasks" class="tasks"></div></section></div></main>
<script type="module">'''+js+'''
class PreviewMeta{constructor(){this.map=new Map()}async get(k){return structuredClone(this.map.get(k))}async put(k,v){this.map.set(k,structuredClone(v))}async delete(k){this.map.delete(k)}async transaction(fn){return fn(this)}}
class PreviewKV{constructor(){this.map=new Map()}async get(k){return this.map.has(k)?JSON.parse(this.map.get(k)):null}async put(k,v){this.map.set(k,v)}}
const meta=new PreviewMeta(),store=new Journal(new PreviewKV(),meta),calendar=new Calendar({}),now=new Date('2026-11-11T12:10:00+07:00');let seq=0,slot='08:30',busy=false;
const $=id=>document.getElementById(id);
function bubble(text,user=false){const el=document.createElement('div');el.className='bubble'+(user?' user':'');el.textContent=text;$('chat').appendChild(el);$('chat').scrollTop=$('chat').scrollHeight}
async function refresh(){const s=await store.load();$('report').textContent=report(s,slot,now);$('revision').textContent='Phiên thử · '+s.revision+' cập nhật';$('tasks').replaceChildren();for(const t of Object.values(s.tasks)){const el=document.createElement('div');el.className='task';const title=document.createElement('strong');title.textContent=t.id+' · '+t.title;const status=document.createElement('span');status.textContent=taskLine(t).split(': ').slice(1).join(': ');el.append(title,status);$('tasks').append(el)}}
async function send(text){if(busy||!text.trim())return;busy=true;bubble(text,true);$('input').value='';$('confirm').replaceChildren();try{const reply=await processText(text,++seq,store,meta,calendar,{},now);bubble(reply);const token=reply.match(/\\/confirm (p\\d+)/)?.[1];if(token){for(const [label,cmd] of [['Xác nhận','/confirm '],['Hủy','/cancel ']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>send(cmd+token);$('confirm').append(b)}}await refresh()}catch(e){bubble('Chưa cập nhật: '+e.message)}finally{busy=false}}
$('form').onsubmit=e=>{e.preventDefault();send($('input').value)};
for(const text of ['/daily','/tasks','Đã xong cống Km3+665','BR đã giao bản vẽ trạm cân','Mai tôi đi công tác','/waiting','/calendar','/english','/history']){const b=document.createElement('button');b.textContent=text;b.onclick=()=>send(text);$('examples').append(b)}
for(const s of ['08:30','11:45','13:30','16:30','21:45']){const b=document.createElement('button');b.textContent=s;b.onclick=()=>{slot=s;refresh()};$('slots').append(b)}
bubble('Chào Yookoo. Tôi theo dõi 9 nhóm công việc, tách riêng hai cống và 6 nhóm BR. Bạn hãy thử báo một việc đã xong; tôi sẽ đưa đề xuất xác nhận trước khi lưu.');await refresh();
</script></html>'''
(r/'preview'/'YOOKOO_PREVIEW.html').write_text(html)
